import React, { useState } from "react";
import ReactDOM from "react-dom/client";

function App() {
  const [showCropForm, setShowCropForm] = useState(false);

  const [crops, setCrops] = useState([
    {
      name: "Wheat",
      area: 3,
      expense: 15000,
      income: 28000,
    },
    {
      name: "Soybean",
      area: 2,
      expense: 12000,
      income: 24000,
    },
  ]);

  const totalExpense = crops.reduce(
    (total, crop) => total + crop.expense,
    0
  );

  const totalIncome = crops.reduce(
    (total, crop) => total + crop.income,
    0
  );

  const totalProfit = totalIncome - totalExpense;

  return (
    <div
      style={{
        minHeight: "100vh",
        backgroundColor: "#f4f7f2",
        fontFamily: "Arial, sans-serif",
      }}
    >
      {/* HEADER */}
      <header
        style={{
          backgroundColor: "#176b36",
          color: "white",
          padding: "18px 40px",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
        }}
      >
        <div>
          <h1 style={{ margin: 0 }}>🌾 Kisan Profit</h1>
          <small>Smart Farming • Better Profit</small>
        </div>

        <div>
          👨‍🌾 Farmer Dashboard
        </div>
      </header>

      {/* MAIN */}
      <main
        style={{
          maxWidth: "1200px",
          margin: "auto",
          padding: "40px 25px",
        }}
      >
        {/* WELCOME */}
        <section>
          <h2
            style={{
              color: "#174d2a",
              fontSize: "32px",
              marginBottom: "8px",
            }}
          >
            Welcome to Kisan Profit 👋
          </h2>

          <p style={{ color: "#666", fontSize: "17px" }}>
            Track your crops, expenses, income and actual farming profit.
          </p>
        </section>

        {/* SUMMARY CARDS */}
        <section
          style={{
            display: "grid",
            gridTemplateColumns:
              "repeat(auto-fit, minmax(220px, 1fr))",
            gap: "20px",
            marginTop: "30px",
          }}
        >
          {/* CROPS */}
          <div
            style={{
              backgroundColor: "white",
              padding: "25px",
              borderRadius: "14px",
              boxShadow: "0 3px 12px rgba(0,0,0,0.08)",
            }}
          >
            <div style={{ fontSize: "30px" }}>🌱</div>
            <p style={{ color: "#777" }}>Total Crops</p>
            <h2>{crops.length}</h2>
          </div>

          {/* EXPENSE */}
          <div
            style={{
              backgroundColor: "white",
              padding: "25px",
              borderRadius: "14px",
              boxShadow: "0 3px 12px rgba(0,0,0,0.08)",
            }}
          >
            <div style={{ fontSize: "30px" }}>💸</div>
            <p style={{ color: "#777" }}>Total Expense</p>
            <h2>₹{totalExpense.toLocaleString()}</h2>
          </div>

          {/* INCOME */}
          <div
            style={{
              backgroundColor: "white",
              padding: "25px",
              borderRadius: "14px",
              boxShadow: "0 3px 12px rgba(0,0,0,0.08)",
            }}
          >
            <div style={{ fontSize: "30px" }}>💰</div>
            <p style={{ color: "#777" }}>Total Income</p>
            <h2>₹{totalIncome.toLocaleString()}</h2>
          </div>

          {/* PROFIT */}
          <div
            style={{
              backgroundColor: "white",
              padding: "25px",
              borderRadius: "14px",
              boxShadow: "0 3px 12px rgba(0,0,0,0.08)",
              borderLeft: "5px solid #176b36",
            }}
          >
            <div style={{ fontSize: "30px" }}>📈</div>
            <p style={{ color: "#777" }}>Net Profit</p>
            <h2 style={{ color: "#176b36" }}>
              ₹{totalProfit.toLocaleString()}
            </h2>
          </div>
        </section>

        {/* ACTION BUTTONS */}
        <section
          style={{
            display: "flex",
            gap: "15px",
            marginTop: "35px",
            flexWrap: "wrap",
          }}
        >
          <button
            onClick={() => setShowCropForm(true)}
            style={{
              backgroundColor: "#176b36",
              color: "white",
              border: "none",
              padding: "14px 24px",
              borderRadius: "8px",
              fontSize: "16px",
              cursor: "pointer",
            }}
          >
            + Add Crop
          </button>

          <button
            style={{
              backgroundColor: "white",
              color: "#176b36",
              border: "1px solid #176b36",
              padding: "14px 24px",
              borderRadius: "8px",
              fontSize: "16px",
              cursor: "pointer",
            }}
          >
            + Add Expense
          </button>

          <button
            style={{
              backgroundColor: "white",
              color: "#176b36",
              border: "1px solid #176b36",
              padding: "14px 24px",
              borderRadius: "8px",
              fontSize: "16px",
              cursor: "pointer",
            }}
          >
            + Add Income
          </button>
        </section>

        {/* CROP TABLE */}
        <section
          style={{
            backgroundColor: "white",
            marginTop: "35px",
            padding: "25px",
            borderRadius: "14px",
            boxShadow: "0 3px 12px rgba(0,0,0,0.08)",
            overflowX: "auto",
          }}
        >
          <h2 style={{ color: "#174d2a" }}>
            📊 Crop Profit Analysis
          </h2>

          <table
            style={{
              width: "100%",
              borderCollapse: "collapse",
              marginTop: "20px",
            }}
          >
            <thead>
              <tr style={{ backgroundColor: "#edf5ee" }}>
                <th style={cellStyle}>Crop</th>
                <th style={cellStyle}>Area</th>
                <th style={cellStyle}>Expense</th>
                <th style={cellStyle}>Income</th>
                <th style={cellStyle}>Profit</th>
              </tr>
            </thead>

            <tbody>
              {crops.map((crop, index) => {
                const profit = crop.income - crop.expense;

                return (
                  <tr key={index}>
                    <td style={cellStyle}>{crop.name}</td>
                    <td style={cellStyle}>
                      {crop.area} acres
                    </td>
                    <td style={cellStyle}>
                      ₹{crop.expense.toLocaleString()}
                    </td>
                    <td style={cellStyle}>
                      ₹{crop.income.toLocaleString()}
                    </td>
                    <td
                      style={{
                        ...cellStyle,
                        color:
                          profit >= 0 ? "#176b36" : "#d32f2f",
                        fontWeight: "bold",
                      }}
                    >
                      ₹{profit.toLocaleString()}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </section>

        {/* FORM */}
        {showCropForm && (
          <section
            style={{
              backgroundColor: "white",
              marginTop: "30px",
              padding: "25px",
              borderRadius: "14px",
              boxShadow: "0 3px 12px rgba(0,0,0,0.1)",
            }}
          >
            <h2>🌱 Add New Crop</h2>

            <p style={{ color: "#666" }}>
              Crop management form will be connected next.
            </p>

            <button
              onClick={() => setShowCropForm(false)}
              style={{
                padding: "10px 20px",
                border: "none",
                borderRadius: "6px",
                cursor: "pointer",
              }}
            >
              Close
            </button>
          </section>
        )}
      </main>
    </div>
  );
}

